            for (var r : regs.getOrDefault(type, List.of())) out.add(type.cast(instance(r)));
            return out;
        }

        private Object instance(Reg r) {
            if (r.scope == Scope.PROTOTYPE) return r.factory.apply(this);
            if (r.instance == null) r.instance = r.factory.apply(this);
